_N = [
("def","definition","critère",3,0,ACSM,"Le coup de chaleur d'exercice associe une température centrale élevée, en général supérieure à 40 °C, et une dysfonction du système nerveux central survenue pendant ou juste après un effort (seuil exact à vérifier)."),
("epi","epidemiology","chiffre",1,0,ACSM,"Il touche surtout les sportifs d'endurance, les recrues et les travailleurs exposés ; la forme classique touche surtout la personne âgée pendant une canicule."),
("mech","basicSciences","mécanisme",1,0,ACSM,"La chaleur produite par les muscles dépasse ce que la peau peut dissiper ; la chaleur lèse directement les cellules et déclenche une réaction inflammatoire puis une défaillance de plusieurs organes."),
("risk","anamnesis","terrain particulier",2,0,ACSM,"Le manque d'acclimatation, une infection fébrile récente, le manque de sommeil, la déshydratation, l'obésité, un faible entraînement et les stimulants favorisent l'accident."),
("classic","anamnesis","terrain particulier",1,0,ACSM+" ; "+OFSP,"La forme classique frappe la personne âgée isolée pendant une canicule ; les diurétiques, les anticholinergiques et les neuroleptiques l'aggravent, et la peau est souvent sèche."),
("car","anamnesis","terrain particulier",1,0,EXP,"Un nourrisson laissé dans une voiture au soleil peut faire un coup de chaleur en quelques minutes, car l'habitacle chauffe très vite."),
("sns","clinicalExam","signe",3,0,ACSM,"La confusion, un comportement bizarre ou agressif, l'ataxie, les convulsions ou le coma signent l'atteinte cérébrale ; dans la forme d'effort, la peau peut rester humide et en sueur."),
("rectal","clinicalExam","examen",2,0,ACSM,"Seule la température rectale (ou œsophagienne) est fiable chez le sportif effondré ; les mesures axillaire, buccale, tympanique ou frontale la sous-estiment."),
("eah","presumptionRedFlags","diagnostic différentiel",2,0,ACSM+" ; "+EXP,"Une hyponatrémie d'effort donne une confusion après une longue épreuve où le sportif a bu beaucoup d'eau, avec une température peu élevée : on mesure la natrémie avant tout soluté hypotonique."),
("ddx","presumptionRedFlags","diagnostic différentiel",1,0,EXP,"On évoque aussi une hypoglycémie, un arrêt cardiaque, une méningite ou un sepsis, et un accident vasculaire cérébral."),
("drugs","presumptionRedFlags","diagnostic différentiel",2,0,EXP,"Hors effort, une hyperthermie fait chercher une hyperthermie maligne d'anesthésie, un syndrome malin des neuroleptiques, un syndrome sérotoninergique ou une intoxication aux sympathomimétiques."),
("exhaust","positiveDiagnosis","critère",2,0,ACSM,"L'épuisement par la chaleur donne fatigue et malaise avec un état mental normal ; c'est l'atteinte du système nerveux central qui définit le coup de chaleur."),
("diagpos","positiveDiagnosis","critère",1,0,ACSM,"Le diagnostic repose sur le contexte, la température rectale et l'atteinte neurologique ; il n'attend aucun examen de laboratoire."),
("bio","workupGoldStandard","examen",2,0,ACSM+" ; "+EXP,"On dose les CK, la créatinine, le potassium, le sodium, le glucose, les transaminases, la coagulation et le lactate pour chercher une rhabdomyolyse, une insuffisance rénale, une atteinte hépatique et une coagulation intravasculaire disséminée."),
("alt","workupAlternatives","examen",1,0,EXP,"On réserve le scanner cérébral et la ponction lombaire au patient dont la conscience ne se normalise pas après le refroidissement ou dont le contexte évoque une autre cause."),
("cwi","acuteManagement","décision",3,0,ACSM,"On immerge le corps jusqu'au cou dans de l'eau glacée sur place, car on refroidit d'abord et on transporte ensuite ; on vise moins de 39 °C dans les 30 minutes qui suivent l'effondrement (délai à vérifier)."),
("stop","acuteManagement","seuil",2,0,ACSM,"On sort le patient du bain vers 38,6 à 39 °C de température rectale, pour éviter une hypothermie de rebond (seuil à vérifier)."),
("altcool","acuteManagement","décision",1,0,ACSM,"Sans bain, on applique des serviettes glacées qu'on renouvelle, on asperge d'eau et on ventile, puis on appelle le 144."),
("antipyr","acuteManagement","piège",2,0,ACSM+" ; "+EXP,"Les antipyrétiques n'agissent pas, car le thermostat hypothalamique n'est pas déréglé, et ils peuvent léser le foie ou le rein ; le dantrolène n'a pas d'indication démontrée."),
("fluids","acuteManagement","décision",1,0,EXP,"On pose une voie veineuse, on donne un cristalloïde isotonique selon l'hémodynamique et la natrémie, et une benzodiazépine en cas de convulsions ou de frissons intenses."),
("rhabdo","hospitalizationComplications","complication",2,0,ACSM+" ; "+EXP,"La rhabdomyolyse peut donner une insuffisance rénale aiguë et une hyperkaliémie ; une coagulation intravasculaire disséminée et une insuffisance hépatique peuvent apparaître dans les 24 à 72 heures (délai à vérifier)."),
("hypoT","hospitalizationComplications","complication",1,0,ACSM,"Un refroidissement prolongé au-delà du seuil d'arrêt provoque une hypothermie de rebond."),
("prono","prognosisDischarge","pronostic",1,0,ACSM,"Le pronostic dépend de la durée de l'hyperthermie : un patient refroidi rapidement sur place survit en général sans séquelle."),
("sortie","prognosisDischarge","décision",1,0,EXP,"Le patient sort quand son état neurologique, sa fonction rénale et ses tests hépatiques se sont normalisés."),
("rtp","chronicManagement","décision",3,0,ACSM,"On reprend l'activité de façon progressive, après normalisation clinique et biologique, sous contrôle médical et avec une nouvelle acclimatation à la chaleur (délais à vérifier)."),
("surv","surveillance","examen",1,0,ACSM+" ; "+EXP,"On suit la température rectale en continu pendant le refroidissement, puis on contrôle CK, créatinine, potassium, transaminases et coagulation pendant 24 à 72 heures."),
("prev","followUpNetwork","prévention",1,0,ACSM,"On acclimate les sportifs sur 10 à 14 jours, on adapte l'effort à la contrainte thermique (indice WBGT), on organise l'hydratation et on prévoit un bain froid sur place (durée à vérifier)."),
("suisse","followUpNetwork","contexte suisse",1,1,OFSP,"En Suisse, l'OFSP et les cantons diffusent des recommandations en cas de canicule, et les réseaux d'aide à domicile repèrent les personnes âgées isolées."),
]
